export function deriveProxyVarDefaults(
  proxyUrls: { host: string; port: number; protocol: string }[] | null | undefined,
): Partial<Record<ProxyVarName, string>> {
  if (!proxyUrls || proxyUrls.length === 0) {
    return {};
  }

  const result: Partial<Record<ProxyVarName, string>> = {};

  for (const entry of proxyUrls) {
    if (!entry.host) { continue; }
    const protocol = entry.protocol?.toLowerCase();
    const hostPort = `${entry.host}:${entry.port}`;

    switch (protocol) {
      case 'http':
      case 'ws':
        if (result.proxy_host === undefined) {
          result.proxy_host = entry.port === 80 ? entry.host : hostPort;
        }
        break;
      case 'https':
      case 'wss':
        if (result.proxy_host === undefined) {
          result.proxy_host = entry.port === 443 ? entry.host : hostPort;
        }
        break;
      case 'grpc':
        if (result.grpc_proxy_host === undefined) {
          result.grpc_proxy_host = hostPort;
        }
        break;
      case 'grpcs':
        if (result.grpcs_proxy_host === undefined) {
          result.grpcs_proxy_host = hostPort;
        }
        break;
      default:
